x.optionTargetCheckDazzle, "panorama/images/spellicons/dazzle_shallow_grave_png.vtex_c") Menu.AddMenuIcon({"Hero Specific","Tiny"," Detect"}, "panorama/images/icon_locked_png.vtex_c")  Menu.AddMenuIcon({"Hero Specific","Tiny"," Target"}, "panorama/images/icon_plus_white_png.vtex_c") Menu.AddMenuIcon({"Hero Specific","Tiny" , " Items"}, "panorama/images/icon_plus_white_png.vtex_c") Menu.AddMenuIcon({"Hero Specific","Tiny"," Abilities"}, "panorama/images/icon_plus_white_png.vtex_c")  local CurentHero = nil TinyHx.LockedTarget = nil TinyHx.myUnitName = nil TinyHx.lastCastTime = 0 TinyHx.lastCastTime2 = 0 TinyHx.lastCastTime3 = 0 TinyHx.lastTick = 0 TinyHx.delay = 0 TinyHx.itemDelay = 0 TinyHx.lastItemCast = 0 TinyHx.lastDefItemPop = 0 TinyHx.lastItemTick = 0 TinyHx.ItemCastStop = false TinyHx.particleNextTime = 0 TinyHx.currentParticle = 0 TinyHx.currentParticleTarget = nil   function TinyHx.ResetGlobalVariables() 	CurentHero = nil 	TinyHx.LockedTarget = nil 	TinyHx.myUnitName = nil 	TinyHx.lastCastTime = 0 	TinyHx.lastCastTime2 = 0 	TinyHx.lastCastTime3 = 0 	TinyHx.lastTick = 0 	TinyHx.delay = 0 	TinyHx.itemDelay = 0 	TinyHx.lastItemCast = 0 	TinyHx.lastDefItemPop = 0 	TinyHx.lastItemTick = 0 	TinyHx.ItemCastStop = false 	TinyHx.isArmletManuallyToggled = false 	TinyHx.isArmletManuallyToggledTime = 0 	TinyHx.armletDelayer = 0 	TinyHx.ControlledUnitCastTime = 0 	TinyHx.ControlledUnitPauseTime = 0 	TinyHx.lastAttackTime = 0 	TinyHx.lastAttackTime2 = 0 	TinyHx.LastTarget = nil 	TinyHx.LastTickManta1 = 0 	TinyHx.LastTickManta2 = 0 	TinyHx.currentParticle = 0 	TinyHx.currentParticleTarget = nil end  function TinyHx.OnGameStart() 	 	TinyHx.ResetGlobalVariables()  end  function TinyHx.OnGameEnd() 	 	TinyHx.ResetGlobalVariables()  end   function TinyHx.OnUpdate() 	 	if not Menu.IsEnabled(TinyHx.optionEnable) then return end 	local myHero = Heroes.GetLocal() 	if TinyHx.myUnitName == "npc_dota_hero_tiny" then end  	if not Engine.IsInGame() then 		TinyHx.ResetGlobalVariables() 	end 	 	if GameRules.GetGameState() < 4 then return end 	if GameRules.GetGameState() > 5 then return end  		if not TinyHx.EIsAlive(myHero) then return end  	local enemy = TinyHx.getComboTarget(myHero)  	if Menu.IsKeyDown(TinyHx.optionComboKey) then 		if Menu.GetValue(TinyHx.optionTargetStyle) < 1 then 			if TinyHx.LockedTarget == nil then 				if enemy then 					TinyHx.LockedTarget = enemy 				else 					TinyHx.LockedTarget = nil 				end 			end 		else 			if enemy then 				TinyHx.LockedTarget = enemy 			else 				TinyHx.LockedTarget = nil 			end 		end 	else 		TinyHx.LockedTarget = nil 	end  	if TinyHx.LockedTarget ~= nil then 		if not TinyHx.EIsAlive(TinyHx.LockedTarget) then 			TinyHx.LockedTarget = nil 		elseif Entity.IsDormant(TinyHx.LockedTarget) then 			TinyHx.LockedTarget = nil 		elseif not NPC.IsEntityInRange(myHero, TinyHx.LockedTarget, 3000) then 			TinyHx.LockedTarget = nil 		end 	end  	if Menu.IsEnabled(TinyHx.optionLockTargetIndicator) then 		TinyHx.TargetIndicator(myHero) 	end  	local comboTarget 		if TinyHx.LockedTarget ~= nil then 			comboTarget = TinyHx.LockedTarget 		else 			if not Menu.IsKeyDown(TinyHx.optionComboKey) then 				comboTarget = enemy 			end 		end 	if comboTarget then 				TinyHx.tinyCombo(myHero, comboTarget) 	end  	if TinyHx.LockedTarget == nil then 		if Menu.IsEnabled(TinyHx.optionMoveToCursor) then 			if Menu.IsKeyDown(TinyHx.optionComboKey) then 				    Player.AttackTarget(Players.GetLocal(), myHero, enemy, false) 				return 			end 		end	 	end   end     TinyHx.EIsAlive = function (entity) 	if entity and entity ~= 0 then 		return Entity.IsAlive(entity) 	else 		return false 	end end  TinyHx.HInRadius = function (vec, radius, teamNum, teamType) 	local tbl = Heroes.InRadius(vec, radius, teamNum, teamType) 	if tbl ~= nil then 		return tbl 	else 		return {} 	end end  function TinyHx.getComboTarget(myHero)  	if not myHero then return end  	local targetingRange = Menu.GetValue(TinyHx.optionTargetRange) 	local mousePos = Input.GetWorldCursorPos()  	local enemyTable = TinyHx.HInRadius(mousePos, targetingRange, Entity.GetTeamNum(myHero), Enum.TeamType.TEAM_ENEMY) 		if #enemyTable < 1 then return end  	local nearestTarget = nil 	local distance = 99999  	for i, v in ipairs(enemyTable) do 		if v and Entity.IsHero(v) then 			if TinyHx.targetChecker(v) ~= nil then 				local enemyDist = (Entity.GetAbsOrigin(v) - mousePos):Length2D() 				if enemyDist < distance then 					nearestTarget = v 					distance = enemyDist 				end 			end 		end 	end  	return nearestTarget or nil  end   function TinyHx.targetChecker(genericEnemyEntity)  	local myHero = Heroes.GetLocal() 		if not myHero then return end  	if genericEnemyEntity and not Entity.IsDormant(genericEnemyEntity) and not NPC.IsIllusion(genericEnemyEntity) and Entity.GetHealth(genericEnemyEntity) > 0 then  		if Menu.IsEnabled(TinyHx.optionTargetCheckAM) then 			if NPC.HasModifier(genericEnemyEntity, "modifier_antimage_spell_shield") then 				return 			end 		end 		if Menu.IsEnabled(TinyHx.optionEnableLorb) then 			if NPC.HasModifier(genericEnemyEntity, "modifier_item_lotus_orb_active") then 				return 			end 		end 		if Menu.IsEnabled(TinyHx.optionEnableBmail) then 			if NPC.HasModifier(genericEnemyEntity, "modifier_item_blade_mail_reflect") and Entity.GetHealth(Heroes.GetLocal()) <= 0.25 * Entity.GetMaxHealth(Heroes.GetLocal()) then 				return 			end 		end 		if Menu.IsEnabled(TinyHx.optionTargetCheckNyx) then 			if NPC.HasModifier(genericEnemyEntity, "modifier_nyx_assassin_spiked_carapace") then 				return 			end 		end 		 		if Menu.IsEnabled(TinyHx.optionTargetCheckUrsa) then 			if NPC.HasModifier(genericEnemyEntity, "modifier_ursa_enrage") then 				return 			end 		end 		if Menu.IsEnabled(TinyHx.optionTargetCheckAbbadon) then 			if NPC.HasModifier(genericEnemyEntity, "modifier_abaddon_borrowed_time") then 				return 			end 		end 		if Menu.IsEnabled(TinyHx.optionTargetCheckDazzle) then 			if NPC.HasModifier(genericEnemyEntity, "modifier_dazzle_shallow_grave") and NPC.GetUnit