x.LockedTarget			 			end 			if TinyHx.currentParticle > 0 then 				Particle.SetControlPoint(TinyHx.currentParticle, 2, Entity.GetOrigin(myHero)) 				Particle.SetControlPoint(TinyHx.currentParticle, 6, Vector(1, 0, 0)) 				Particle.SetControlPoint(TinyHx.currentParticle, 7, Entity.GetOrigin(TinyHx.currentParticleTarget)) 			end 		end 	end  end  function TinyHx.heroCanCastSpells(myHero, enemy)  	if not myHero then return false end 	if not TinyHx.EIsAlive(myHero) then return false end  	if NPC.IsSilenced(myHero) then return false end  	if NPC.IsStunned(myHero) then return false end 	if NPC.HasModifier(myHero, "modifier_bashed") then return false end 	if NPC.HasState(myHero, Enum.ModifierState.MODIFIER_STATE_INVULNERABLE) then return false end	 	if NPC.HasModifier(myHero, "modifier_eul_cyclone") then return false end 	if NPC.HasModifier(myHero, "modifier_obsidian_destroyer_astral_imprisonment_prison") then return false end 	if NPC.HasModifier(myHero, "modifier_shadow_demon_disruption") then return false end	 	if NPC.HasModifier(myHero, "modifier_invoker_tornado") then return false end 	if NPC.HasState(myHero, Enum.ModifierState.MODIFIER_STATE_HEXED) then return false end 	if NPC.HasModifier(myHero, "modifier_legion_commander_duel") then return false end 	if NPC.HasModifier(myHero, "modifier_axe_berserkers_call") then return false end 	if NPC.HasModifier(myHero, "modifier_winter_wyvern_winters_curse") then return false end 	if NPC.HasModifier(myHero, "modifier_bane_fiends_grip") then return false end 	if NPC.HasModifier(myHero, "modifier_bane_nightmare") then return false end 	if NPC.HasModifier(myHero, "modifier_faceless_void_chronosphere_freeze") then return false end 	if NPC.HasModifier(myHero, "modifier_enigma_black_hole_pull") then return false end 	if NPC.HasModifier(myHero, "modifier_magnataur_reverse_polarity") then return false end 	if NPC.HasModifier(myHero, "modifier_pudge_dismember") then return false end 	if NPC.HasModifier(myHero, "modifier_shadow_shaman_shackles") then return false end 	if NPC.HasModifier(myHero, "modifier_techies_stasis_trap_stunned") then return false end 	if NPC.HasModifier(myHero, "modifier_storm_spirit_electric_vortex_pull") then return false end 	if NPC.HasModifier(myHero, "modifier_tidehunter_ravage") then return false end 	if NPC.HasModifier(myHero, "modifier_windrunner_shackle_shot") then return false end 	if NPC.HasModifier(myHero, "modifier_item_nullifier_mute") then return false end  	if enemy then 		if NPC.HasModifier(enemy, "modifier_item_aeon_disk_buff") then return false end 	end  	return true	  end   function TinyHx.tinyCombo(myHero, enemy) 	if TinyHx.myUnitName == "npc_dota_hero_tiny" then end  	if not Menu.IsEnabled(TinyHx.optionEnable) then return end 	if not NPC.IsEntityInRange(myHero, enemy, 3000)	then return end          local avalanche = NPC.GetAbilityByIndex(myHero, 0)     local toss = NPC.GetAbilityByIndex(myHero, 1)     local myMana = NPC.GetMana(myHero)  	local blink = NPC.GetItem(myHero, "item_blink", true) 	local mom = NPC.GetItem(myHero, "item_mask_of_madness", true) 	local urn = NPC.GetItem(myHero, "item_urn_of_shadows", true) 	local vessel = NPC.GetItem(myHero, "item_spirit_vessel", true) 	local hex = NPC.GetItem(myHero, "item_sheepstick", true) 	local nullifier = NPC.GetItem(myHero, "item_nullifier", true) 	local diffusal = NPC.GetItem(myHero, "item_diffusal_blade", true) 	local mjolnir = NPC.GetItem(myHero, "item_mjollnir", true) 	local halberd = NPC.GetItem(myHero, "item_heavens_halberd", true) 	local abyssal = NPC.GetItem(myHero, "item_abyssal_blade", true) 	local armlet = NPC.GetItem(myHero, "item_armlet", true) 	local bloodthorn = NPC.GetItem(myHero, "item_bloodthorn", true) 	local bkb = NPC.GetItem(myHero, "item_black_king_bar", true) 	local courage = NPC.GetItem(myHero, "item_medallion_of_courage", true) 	local solar = NPC.GetItem(myHero, "item_solar_crest", true) 	local blademail = NPC.GetItem(myHero, "item_blade_mail", true) 	local orchid = NPC.GetItem(myHero, "item_orchid", true) 	local lotus = NPC.GetItem(myHero, "item_lotus_orb", true) 	local cyclone = NPC.GetItem(myHero, "item_cyclone", true) 	local satanic = NPC.GetItem(myHero, "item_satanic", true) 	local force = NPC.GetItem(myHero, "item_force_staff", true) 	local pike = NPC.GetItem(myHero, "item_hurricane_pike", true) 	local eblade = NPC.GetItem(myHero, "item_ethereal_blade", true) 	local phase = NPC.GetItem(myHero, "item_phase_boots", true) 	local medallion = NPC.GetItem(myHero, "item_medallion_of_courage") 	local rod = NPC.GetItem(myHero, "item_rod_of_atos") 	local solar = NPC.GetItem(myHero, "item_solar_crest") 	local hh = NPC.GetItem(myHero, "item_heavens_halberd") 	local eul = NPC.GetItem(myHero, "item_cyclone") 	local diffusal = NPC.GetItem(myHero, "item_diffusal_blade") 	local dagon = NPC.GetItem(myHero, "item_dagon", true) 	if not dagon then 		for i = 2, 5 do 			local dagon = NPC.GetItem(myHero, "item_dagon_" .. i, true) 			if dagon then break end 		end 	end 	local discord = NPC.GetItem(myHero, "item_veil_of_discord", true) 	local shiva = NPC.GetItem(myHero, "item_shivas_guard", true) 	local refresher = NPC.GetItem(myHero, "item_refresher", true) 	local soulring = NPC.GetItem(myHero, "item_soul_ring", true) 	local manta = NPC.GetItem(myHero, "item_manta", true) 	local necro = NPC.GetItem(myHero, "item_necronomicon", true) 	local Sring = NPC.GetItem(myHero, "item_soul_ring", true) 	if not necro then 		for i = 2, 3 do 			local necro = NPC.GetItem(myHero, "item_necronomicon_" .. i, true) 			if necro then break end 		end 	end 	local Fstaff = NPC.GetItem(myHero, "item_force_staff", true)     local Hstaff = NPC.GetItem(myHero, "item_hurricane_pike", true) 	local shadowblyad = NPC.GetItem(myHero, "item_invis_sword", true)     local silveredge = NPC.GetItem(myHero, "item_silver_edge", true)     local glimmer = NPC.GetItem(myHero, "item_glimmer_cape", true)  	if Menu.IsKeyDown(TinyHx.optionComboKey) and Entity.GetHealth(enemy) > 0 and not NPC.HasState(enemy, Enum.ModifierState.MODIFIER_STATE_MAGIC_IMMUNE) and TinyHx.heroCanCastSpells(myHero, enemy) == true then 	Player.AttackTarget(Players.GetLocal(), myHero, enemy, false) 		 	if not NPC.IsLinkensProtected(enemy) and Menu.IsEnabled(TinyHx.optionEnableSring) and Sring and Ability.IsCastable(Sring, 0) then Ability.CastNoTarget(Sring); return end 	if not NPC.IsEntityInRange(myHero, enemy, 275) then 		if Menu.IsEnabled(TinyHx.optionEnableBlink) and blink and Ability.IsReady(blink) then 			if NPC.IsEntityInRange(myHero, enemy, 1150) then 				Ability.CastPosition(blink, Entity.GetAbsOrigin(enemy)) 				return 			end 		end 	else 		if avalanche and Ability.IsCastable(avalanche, myMana) then  			Ability.CastPosition(avalanche, Entity.GetAbsOrigin(enemy)) 			TinyHx.lastTick = os.clock() 		end     		if TinyHx.SleepReady(0.2) and toss and Ability.IsCastable(toss, myMana) then  			Ability.CastTarget(toss, enemy) 			return  		end 	end 	if NPC.HasState(enemy, Enum.ModifierState.MODIFIER_STATE_MAGIC_IMMUNE) then return end 	if Menu.IsEnabled(TinyHx.optionEnableLorb) and NPC.HasModifier(enemy, "modifier_item_lotus_orb_active") then return true end     if Menu.IsEnabled(TinyHx.optionEnableBmail) and NPC.HasModifier(enemy, "modifier_item_blade_mail_reflect") then return true end 	if Menu.IsEnabled(TinyHx.optionTargetCheckNyx) and NPC.HasModifier(enemy, "modifier_nyx_assassin_spiked_carapace") then return true end 	if Menu.IsEnabled(TinyHx.optionTargetCheckAM) and NPC.HasModifier(enemy, "modifier_antimage_spell_shield") then return true end 	if Menu.IsEnabled(TinyHx.optionTargetCheckUrsa) and NPC.HasModifier(enemy, "modifier_ursa_enrage") then return true end 	if Menu.IsEnabled(TinyHx.optionTargetCheckAbbadon) and NPC.HasModifier(enemy, "modifier_abaddon_borrowed_time") then return true end if Menu.IsEnabled(TinyHx.optionTargetCheckDazzle) and NPC.HasModifier(enemy, "modifier_dazzle_shallow_grave") then return true end 	 	  	if Menu.IsEnabled(TinyHx.optionEnableLinkens1) and hex and Ability.IsCastable(hex, myMana) and NPC.IsEntityInRange(enemy, myHero, Ability.GetCastRange(hex) - 10) and NPC.IsLinkensProtected(enemy) then Ability.CastTarget(hex, enemy); return end 	if Menu.IsEnabled(TinyHx.optionEnableLinkens2) and bloodthorn and Ability.IsCastable(bloodthorn, myMana) and NPC.IsEntityInRange(enemy, myHero, Ability.GetCastRange(bloodthorn) - 10) and NPC.IsLinkensProtected(enemy) then Ability.CastTarget(bloodthorn, enemy); return end     if Menu.IsEnabled(TinyHx.optionEnableLinkens3) and orchid and Ability.IsCastable(orchid, myMana) and NPC.IsEntityInRange(enemy, myHero, Ability.GetCastRange(orchid) - 10) and NPC.IsLinkensProtected(enemy) then Ability.CastTarget(orchid, enemy); return end 	if Menu.IsEnabled(TinyHx.optionEnableLinkens4) and nullifier and Ability.IsCastable(nullifier, myMana) and NPC.IsEntityInRange(enemy, myHero, Ability.GetCastRange(nullifier) - 10) and NPC.IsLinkensProtected(enemy) then Ability.CastTarget(nullifier, enemy); return end 	if Menu.IsEnabled(TinyHx.optionEnableLinkens5) and rod and Ability.IsCastable(rod, myMana) and NPC.IsEntityInRange(enemy, myHero, Ability.GetCastRange(rod) - 10) and NPC.IsLinkensProtected(enemy)then Ability.CastTarget(rod, enemy); return end     if Menu.IsEnabled(TinyHx.optionEnableLinkens6) and Fstaff and Ability.IsCastable(Fstaff, myMana) and NPC.IsEntityInRange(enemy, myHero, Ability.GetCastRange(Fstaff) - 10) and NPC.IsLinkensProtected(enemy) then Ability.CastTarget(Fstaff, enemy); return end     if Menu.IsEnabled(TinyHx.optionEnableLinkens7) and Hstaff and Ability.IsCastable(Hstaff, myMana) and NPC.IsEntityInRange(enemy, myHero, Ability.GetCastRange(Hstaff) - 10) and NPC.IsLinkensProtected(enemy) then Ability.CastTarget(Hstaff, enemy); return end     if Menu.IsEnabled(TinyHx.optionEnableLinkens8) and eul and Ability.IsCastable(eul, myMana) and NPC.IsEntityInRange(enemy, myHero, Ability.GetCastRange(eul) - 10) and NPC.IsLinkensProtected(enemy) then Ability.CastTarget(eul, enemy); return end  	if not NPC.IsLinkensProtected(enemy) and Menu.IsEnabled(TinyHx.optionSilence) and orchid and Ability.IsCastable(orchid,myMana)  and NPC.IsEntityInRange(enemy, myHero, Ability.GetCastRange(orchid) - 10) then Ability.CastTarget(orchid, enemy) end 	if not NPC.IsLinkensProtected(enemy) and Menu.IsEnabled(TinyHx.optionbloodthorn) and bloodthorn and Ability.IsCastable(bloodthorn, myMana) and NPC.IsEntityInRange(enemy, myHero, Ability.GetCastRange(bloodthorn) - 10) then Ability.CastTarget(bloodthorn, enemy) return end 	if not NPC.IsLinkensProtected(enemy) and Menu.IsEnabled(TinyHx.optionEnableDiffusal) and diffusal and  Ability.IsCastable(diffusal, 0) and NPC.IsEntityInRange(enemy, myHero, Ability.GetCastRange(diffusal) - 10) then Ability.CastTarget(diffusal, enemy) end 	if not NPC.IsLinkensProtected(enemy) and Menu.IsEnabled(TinyHx.optionEnableRod) and rod and Ability.IsCastable(rod,myMana)  and NPC.IsEntityInRange(enemy, myHero, Ability.GetCastRange(rod) - 10) then Ability.CastTarget(rod, enemy) end 	if Menu.IsEnabled(TinyHx.optionEnableMedallion) and medallion  and Ability.IsCastable(medallion, myMana)  and NPC.IsEntityInRange(enemy, myHero, Ability.GetCastRange(medallion) - 10) then Ability.CastTarget(medallion, enemy) end 	if Menu.IsEnabled(TinyHx.optionEnableSolar) and solar and  Ability.IsCastable(solar, myMana) then Ability.CastTarget(solar, enemy) end 	 	if not NPC.IsLinkensProtected(enemy) and Menu.IsEnabled(TinyHx.optionEnableHex) and hex and Ability.IsCastable(hex, myMana) and NPC.IsEntityInRange(enemy, myHero, Ability.GetCastRange(hex) - 10) then Ability.CastTarget(hex, enemy); return end 	if Menu.IsEnabled(TinyHx.optionBkb) and bkb and Ability.IsCastable(bkb, myMana) and Ability.IsReady(bkb) then Ability.CastNoTarget(bkb) return end 	if not NPC.IsLinkensProtected(enemy) and Menu.IsEnabled(TinyHx.optionNullifier) and nullifier and Ability.IsCastable(nullifier, myMana)  and NPC.IsEntityInRange(enemy, myHero, Ability.GetCastRange(nullifier) - 10)then Ability.CastTarget(nullifier, enemy)  return end     if Menu.IsEnabled(TinyHx.optionMom) and mom and Ability.IsCastable(mom, myMana) and Ability.IsReady(mom) then Ability.CastNoTarget(mom) return end 	if not NPC.IsLinkensProtected(enemy) and Menu.IsEnabled(TinyHx.optionAbyssal) and abyssal and Ability.IsCastable(abyssal, myMana) and Ability.IsReady(abyssal) and not NPC.HasState(enemy, Enum.ModifierState.MODIFIER_STATE_STUNNED) and not NPC.HasState(enemy, Enum.ModifierState.MODIFIER_STATE_HEXED) then Ability.CastTarget(abyssal, enemy) return end 	if glimmer and Menu.IsEnabled(TinyHx.optionEnableGlimmer) then Ability.CastTarget(glimmer, myHero); return end  end end return TinyHx    
